test("today permission scenario 3", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "floor", "0.50");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "proof-threshold", "3.00");
  expect(await ui.setRole(pg_uma, "vic", "viewer")).toBe(true);
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  await ui.setSetting(pg_uma, "pot", "33.33");
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-even", "2026-03-10", "half-even")).toBe(true);
  await ui.setSetting(pg_uma, "review-threshold", "1.50");
  expect(await ui.addGrade(pg_uma, "D")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50", "from": "2026-03-16", "to": "2026-03-25"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P2", "from": "2026-03-16", "to": "2026-03-31"})).toBe(true);
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C", "terms": "20", "contact": "ben@x"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"}));
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "tags": "c"}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ada", "share": "60.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "40.00"})).toBe(true);
  expect(await ui.editPerson(pg_uma, p_ben, {"terms": "3", "termsFrom": "2026-03-01"})).toBe(true);
  expect(await ui.inlineGrade(pg_uma, p_ada, "A")).toBe(true);
  expect(await ui.ratePreview(pg_uma, "A", "12.50")).toEqual({ count: 0, diff: "0.00" });
  expect(await ui.statement(pg_uma, p_ben)).toBe(true);
  await ui.setToday(pg_uma, "2026-04-12");
  expect(await ui.ratePreview(pg_uma, "B", "33.33")).toEqual({ count: 0, diff: "0.00" });
  expect(await ui.setSettingDated(pg_uma, "late-pct", "0.00", "2026-03-15", "0.00")).toBe(true);
  const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "3.33", "date": "2026-03-09", "note": "n"}));
  await ui.refresh(pg_uma);
  expect(await ui.movePerson(pg_uma, p_ben, "down")).toBe(false);
  expect(await ui.bulkRetire(pg_uma, [p_cam, p_ada], "2026-02-10")).toBe(2);
  await ui.showRetired(pg_uma, true);
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "12.50", "date": "2026-02-10", "note": "n"}));
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  await ui.showRetired(pg_wes, true);
  expect(await ui.flag(pg_wes, p_ada, "late", "2026-03-12", "")).toBe(true);
  await ui.refresh(pg_wes);
  expect(await ui.merge(pg_wes, p_ada, "Ben")).toBe(false);
  await ui.refresh(pg_wes);
  expect(await ui.bulkReassign(pg_wes, [c_ben_0, c_cam_0], "Cam")).toEqual({ reassigned: 1, refused: 1 });
  expect(await ui.addClaim(pg_wes, p_ada, {"amount": "0.04", "date": "2026-02-25"})).toBeNull();
  await ui.refresh(pg_wes);
  expect(await ui.claimAction(pg_wes, c_ben_0, "void")).toBe(true);
  await ui.refresh(pg_wes);
  expect(await ui.flag(pg_wes, p_ada, "late", "2026-03-12", "")).toBe(true);
  expect(await ui.editClaim(pg_wes, c_cam_0, {"date": "2026-03-20"})).toBe(false);
  await ui.refresh(pg_uma);
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  await ui.refresh(pg_wes);
  expect(await ui.merge(pg_wes, p_ada, "Ben")).toBe(false);
  await ui.refresh(pg_wes);
  expect(await ui.bulkReassign(pg_wes, [c_cam_0], "Ada")).toEqual({ reassigned: 1, refused: 0 });
  await ui.setAsOf(pg_wes, "2026-04-02");
  await ui.refresh(pg_wes);
  await ui.expectAudit(sheet, [
  ]);
  await ui.clearAsOf(pg_wes);
  await ui.refresh(pg_wes);
  expect(await ui.archive(pg_wes)).toBe(true);
  expect(await ui.addClaim(pg_wes, p_ben, {"amount": "10.25"})).toBeNull();
